" fill="#0f172a">Kendi cümlelerinle anlat: Olgu → Bağlam → Neden → Sonuç → Yorum</text></svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
